#' DML: Partially Linear Regression
#'
#' 
#' @param data .
#' @param outcome .
#' @param treat .
#' @param covs .
#' @param lrn_l .
#' @param lrn_m .
#' @param rule .
#' @param folds .
#' @param reps .
#' @param seed .
#' @param level .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$est} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$nuis} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$reps} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$est$asDF}
#'
#' \code{as.data.frame(results$est)}
#'
#' @export
dmlplr <- function(
    data,
    outcome,
    treat,
    covs,
    lrn_l = "lasso",
    lrn_m = "lasso",
    rule = "lambda.min",
    folds = 5,
    reps = 1,
    seed = 1234,
    level = 95,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("dmlplr requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(treat)) treat <- jmvcore::resolveQuo(jmvcore::enquo(treat))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(treat), treat, NULL),
            `if`( ! missing(covs), covs, NULL))


    options <- dmlplrOptions$new(
        outcome = outcome,
        treat = treat,
        covs = covs,
        lrn_l = lrn_l,
        lrn_m = lrn_m,
        rule = rule,
        folds = folds,
        reps = reps,
        seed = seed,
        level = level,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- dmlplrClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

